import{_ as e,c as n,o as a,a1 as r}from"./chunks/framework.C3Hmo1as.js";const u=JSON.parse('{"title":"为什么要多 Agent","description":"多 Agent 架构：何时拆分、如何协作与工程实践","frontmatter":{"title":"为什么要多 Agent","description":"多 Agent 架构：何时拆分、如何协作与工程实践","date":"2026-10-24T00:00:00.000Z","tags":["多 Agent"]},"headers":[],"relativePath":"ai/understanding-multi-agent-architecture.md","filePath":"ai/understanding-multi-agent-architecture.md"}'),l={name:"ai/understanding-multi-agent-architecture.md"};function o(i,t,g,s,h,A){return a(),n("div",null,[...t[0]||(t[0]=[r('<h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>在大模型应用日益复杂的今天，单个 Agent 越来越难以胜任需要多步骤推理、多工具调用、多角色协作的任务。于是「多 Agent 架构」成为了热门话题——但多 Agent 不是银弹。拆得好，事半功倍；拆不好，反而引入更多复杂度和成本。</p><p>本文将从「为什么要拆」「怎么拆」「怎么通信」「结果如何汇总」「工程上要管住什么」五个维度，系统梳理多 Agent 架构的设计思路与实践经验。</p><h2 id="一、为什么要拆-单-agent-的四个瓶颈" tabindex="-1">一、为什么要拆：单 Agent 的四个瓶颈 <a class="header-anchor" href="#一、为什么要拆-单-agent-的四个瓶颈" aria-label="Permalink to &quot;一、为什么要拆：单 Agent 的四个瓶颈&quot;">​</a></h2><p>一个 Agent 的核心循环是：模型读上下文，决定调哪个工具，把结果放回上下文，再决定下一步。任务一复杂，这个循环就会在四个地方卡住。</p><h3 id="_1-上下文被中间结果塞满" tabindex="-1">1. 上下文被中间结果塞满 <a class="header-anchor" href="#_1-上下文被中间结果塞满" aria-label="Permalink to &quot;1. 上下文被中间结果塞满&quot;">​</a></h3><p>查日志、搜代码、翻网页——读进来的东西大多只用一次，却一直占着上下文，也分散了模型对任务本身的注意力。一个子 Agent 探索时可能用掉几万 token，但交回主 Agent 的往往只是一两千 token 的摘要。</p><p><strong>隔离上下文</strong>是拆分的首要理由之一：让做了大量探索的 Agent 在自己的沙盒里工作，不要让它污染指挥部的上下文。</p><h3 id="_2-工具太多、太相似-选不准" tabindex="-1">2. 工具太多、太相似，选不准 <a class="header-anchor" href="#_2-工具太多、太相似-选不准" aria-label="Permalink to &quot;2. 工具太多、太相似，选不准&quot;">​</a></h3><p>工具数量本身不是问题，问题在于工具之间是否相似、重叠。有的系统能用好 15 个以上界限清楚的工具，有的不到 10 个互相重叠的工具就开始选错。当工具数量多到模型频繁选错时，按领域拆给不同的 Agent 是有效的解法。</p><h3 id="_3-一个提示词里塞了太多分支" tabindex="-1">3. 一个提示词里塞了太多分支 <a class="header-anchor" href="#_3-一个提示词里塞了太多分支" aria-label="Permalink to &quot;3. 一个提示词里塞了太多分支&quot;">​</a></h3><p>规则里全是「如果……就……否则……」，改一处牵动别处。还有一种常见问题是<strong>角色冲突</strong>：同一个上下文里既写代码又审代码，审的时候带着写的时候的假设，很难看出自己的错。把不同职责拆给不同 Agent，能从根本上解决这个问题。</p><h3 id="_4-互不依赖的子任务只能串行执行" tabindex="-1">4. 互不依赖的子任务只能串行执行 <a class="header-anchor" href="#_4-互不依赖的子任务只能串行执行" aria-label="Permalink to &quot;4. 互不依赖的子任务只能串行执行&quot;">​</a></h3><p>查五个竞品、看十个模块——单 Agent 只能轮流来，每做完一件，上下文里就多一堆材料。让主 Agent 一次派出多个子 Agent 同时搜索，每个子 Agent 也同时调多个工具，复杂问题的研究时间最多可以缩短九成。</p><p><strong>这四种情况，拆的理由各不相同</strong>：前两种是隔离上下文和工具，第三种是分开职责，第四种才是并行。理解这些区别，比简单地说「任务复杂所以拆」要有说服力得多。</p><h2 id="二、多-agent-的代价" tabindex="-1">二、多 Agent 的代价 <a class="header-anchor" href="#二、多-agent-的代价" aria-label="Permalink to &quot;二、多 Agent 的代价&quot;">​</a></h2><p>拆分不是免费的。多 Agent 架构会引入以下几类额外成本：</p><ul><li><strong>Token 成本</strong>：Agent 的 token 用量一般是普通对话的 4 倍左右，多 Agent 系统可达 15 倍。多 Agent 表现更好的一部分原因，来自它能把更多 token 花到任务上。</li><li><strong>协调开销</strong>：主 Agent 要拆任务、写任务说明、读报告、核对版本、纠正工具给出的错误结论。</li><li><strong>信息丢失与决策冲突</strong>：子 Agent 各自只看到自己那一块，各自的决定说得通，放在一起却对不上。共享上下文、共享完整的过程记录，是避免这类问题的关键。</li><li><strong>错误累积</strong>：一个 Agent 的错误结论，到了下游就成了已知事实。Agent 有状态，错误会累积。</li></ul><h2 id="三、什么任务值得拆" tabindex="-1">三、什么任务值得拆 <a class="header-anchor" href="#三、什么任务值得拆" aria-label="Permalink to &quot;三、什么任务值得拆&quot;">​</a></h2><p>以下几类任务适合拆成多 Agent：</p><ul><li><strong>子任务之间依赖少</strong>，可以各做各的，比如广度优先的调研、几个来源分头检索、按模块分头审查。</li><li><strong>过程很长、结论很短</strong>，比如读大量日志、翻代码，最后只要一个结论。</li><li><strong>需要不同的工具或权限</strong>，比如只读的检索和能写的执行。</li><li><strong>需要一个没参与过程的人来检查</strong>。</li><li><strong>任务够值钱</strong>——多 Agent 只适合价值高到付得起额外开销的任务。</li></ul><p>以下几类任务<strong>不适合拆</strong>：</p><ul><li>各部分强依赖，要共享同一套决策。</li><li>一个 Agent 几步就能做完的任务。</li><li>流程固定、每一步都能写死的任务——用 Workflow 更稳。</li></ul><h3 id="agent-还是-skill" tabindex="-1">Agent 还是 Skill？ <a class="header-anchor" href="#agent-还是-skill" aria-label="Permalink to &quot;Agent 还是 Skill？&quot;">​</a></h3><p>区分这两个概念很重要：</p><ul><li><strong>Skill</strong> 是一份做事的说明，可以带上脚本和资料，用到时加载进当前 Agent 的上下文。活还是这个 Agent 在干，上下文和权限都是同一套。</li><li><strong>子 Agent</strong> 是另起炉灶：每个子 Agent 在自己的上下文窗口里运行，有自己的系统提示词、可用工具和独立的权限，做完只把摘要交回主对话。</li></ul><p>简单说：缺的是「会不会做」，加 Skill；缺的是「做的时候别把主上下文弄乱」「要用不同的权限」「要一个独立的检查者」「要并行跑好几轮」，才拆成 Agent。</p><h2 id="四、怎么拆-结构、边界与任务说明" tabindex="-1">四、怎么拆：结构、边界与任务说明 <a class="header-anchor" href="#四、怎么拆-结构、边界与任务说明" aria-label="Permalink to &quot;四、怎么拆：结构、边界与任务说明&quot;">​</a></h2><h3 id="_4-1-几种常见结构" tabindex="-1">4.1 几种常见结构 <a class="header-anchor" href="#_4-1-几种常见结构" aria-label="Permalink to &quot;4.1 几种常见结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结构</th><th>描述</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>主从（Manager）</strong></td><td>一个主 Agent 拆任务、派活、汇总，子 Agent 只对主 Agent 负责</td><td>需要一个 Agent 掌控流程、最后综合结果的任务</td></tr><tr><td><strong>流水线</strong></td><td>按阶段排好，一个 Agent 做完交给下一个</td><td>步骤固定、顺序明确的流程</td></tr><tr><td><strong>并行分片</strong></td><td>同一类任务切成几份，几个子 Agent 各做一份，再合并</td><td>长文档按章节切开各自抽取，再汇总</td></tr><tr><td><strong>执行加审查</strong></td><td>一个干活，一个检查，不通过就打回</td><td>需要质量保障的生成任务</td></tr><tr><td><strong>按意图转交</strong></td><td>前台分诊 Agent 判断用户要什么，把对话交给对应专职 Agent</td><td>客服等不需要居中掌控的场景</td></tr></tbody></table><p>主从结构还可以嵌套：主 Agent 下面是编排 Agent，编排 Agent 下面是原子 Agent。每多一层就多一次转述和等待，只有下面的 Agent 多到一个主 Agent 管不过来，或者各层权限确实不同时，才值得加。</p><h3 id="_4-2-按什么边界拆" tabindex="-1">4.2 按什么边界拆 <a class="header-anchor" href="#_4-2-按什么边界拆" aria-label="Permalink to &quot;4.2 按什么边界拆&quot;">​</a></h3><p>好的拆分边界应该满足：</p><ul><li><strong>上下文边界</strong>：子 Agent 拿着一份任务说明就能干完，不需要知道主 Agent 之前的全部讨论。</li><li><strong>工具和权限边界</strong>：只读的和能写的分开，碰生产数据的单独一个。</li><li><strong>能单独验收</strong>：子 Agent 的产出要能单独检查，比如测试是否通过、文件是否生成、结论有没有出处。</li></ul><p>「按职位起名」不等于找到了边界。「产品经理 Agent」「架构师 Agent」「程序员 Agent」如果读的是同一批材料、做的是互相依赖的决定，拆完只是多了几次转述。</p><h3 id="_4-3-预定义还是动态创建" tabindex="-1">4.3 预定义还是动态创建 <a class="header-anchor" href="#_4-3-预定义还是动态创建" aria-label="Permalink to &quot;4.3 预定义还是动态创建&quot;">​</a></h3><ul><li><strong>预定义</strong>：每种子 Agent 的提示词、工具和权限提前写好，主 Agent 只决定派谁、派什么任务。好处是行为可预期、好测试。</li><li><strong>动态创建</strong>：主 Agent 临场写任务说明，自己决定派几个。灵活，但要有上限。</li></ul><p>常见做法是两者结合：子 Agent 的类型预先定义，具体任务动态下发。</p><h3 id="_4-4-给子-agent-的任务说明" tabindex="-1">4.4 给子 Agent 的任务说明 <a class="header-anchor" href="#_4-4-给子-agent-的任务说明" aria-label="Permalink to &quot;4.4 给子 Agent 的任务说明&quot;">​</a></h3><p>子 Agent 从一个干净的上下文开始，看不到主 Agent 之前聊过什么。任务说明至少应写清六样：</p><ol><li><strong>要交付什么</strong></li><li><strong>做什么、不做什么</strong>，和别的子 Agent 怎么分界</li><li><strong>已经确认的事实和相关文件的路径</strong>，免得重查</li><li><strong>用哪些工具</strong>，优先看哪些来源</li><li><strong>交回的格式</strong></li><li><strong>做到什么程度算完成</strong>，最多花多少步、多少 token</li></ol><p>检验办法很简单：把这份说明交给一个没参与讨论的新同事，他能不能直接开工。</p><h3 id="_4-5-子-agent-能不能再派子-agent" tabindex="-1">4.5 子 Agent 能不能再派子 Agent <a class="header-anchor" href="#_4-5-子-agent-能不能再派子-agent" aria-label="Permalink to &quot;4.5 子 Agent 能不能再派子 Agent&quot;">​</a></h3><p>嵌套是允许的，但需要管控：</p><ul><li><strong>深度限制</strong>：最深到主对话下面第三层，层数可配置。</li><li><strong>并发数限制</strong>：同一个会话里同时运行的子 Agent 有上限。</li><li><strong>预算限制</strong>：整棵树共用预算，子 Agent 继承的是剩余预算。</li><li><strong>循环检测</strong>：每次派生都带上祖先链，记下谁派的谁，派之前检查有没有绕回去。</li><li><strong>兜底策略</strong>：全局的步数和时间上限。</li></ul><h2 id="五、怎么通信-三种模式" tabindex="-1">五、怎么通信：三种模式 <a class="header-anchor" href="#五、怎么通信-三种模式" aria-label="Permalink to &quot;五、怎么通信：三种模式&quot;">​</a></h2><h3 id="_5-1-经主-agent-中转" tabindex="-1">5.1 经主 Agent 中转 <a class="header-anchor" href="#_5-1-经主-agent-中转" aria-label="Permalink to &quot;5.1 经主 Agent 中转&quot;">​</a></h3><p>子 Agent 只和主 Agent 说话，彼此看不见。好处是好控制、好追踪；代价是主 Agent 成了瓶颈，所有报告都要进它的上下文。</p><h3 id="_5-2-共享状态-黑板模式" tabindex="-1">5.2 共享状态（黑板模式） <a class="header-anchor" href="#_5-2-共享状态-黑板模式" aria-label="Permalink to &quot;5.2 共享状态（黑板模式）&quot;">​</a></h3><p>大家读写同一块存储，比如一张任务表、一个状态对象、一个共享目录。子 Agent 之间不用直接对话，看黑板就知道进度。要管住的是写入：一个任务只能被一个 Agent 认领；同一份数据只有一个权威副本，写入带版本，冲突能被发现。</p><h3 id="_5-3-直接对话或转交" tabindex="-1">5.3 直接对话或转交 <a class="header-anchor" href="#_5-3-直接对话或转交" aria-label="Permalink to &quot;5.3 直接对话或转交&quot;">​</a></h3><p>A 直接给 B 发消息，或者把整个对话交给 B。这种模式灵活，但要有明确的规则，比如由一个协调者指定下一个轮到谁。没有规则的群聊最容易抢答。</p><h3 id="_5-4-路由-派给谁" tabindex="-1">5.4 路由：派给谁 <a class="header-anchor" href="#_5-4-路由-派给谁" aria-label="Permalink to &quot;5.4 路由：派给谁&quot;">​</a></h3><p>主 Agent 或路由节点要决定一件事交给哪个子 Agent，可以用规则、分类模型，或者让大模型按各个子 Agent 的说明来选。无论哪种方式，都要做到：</p><ul><li>说明写清负责什么、不负责什么，彼此不能重叠</li><li>准确率靠评测持续提升</li><li>给路由留一个「拿不准」的出口</li><li>派错了要能退回</li></ul><h3 id="_5-5-a2a-与-mcp-的分工" tabindex="-1">5.5 A2A 与 MCP 的分工 <a class="header-anchor" href="#_5-5-a2a-与-mcp-的分工" aria-label="Permalink to &quot;5.5 A2A 与 MCP 的分工&quot;">​</a></h3><p>当 Agent 由不同团队、不同厂商开发、分开部署时，需要协议来连接它们：</p><ul><li><strong>MCP（Model Context Protocol）</strong>：把每个 Agent 连到它自己的工具。调 MCP 的工具像调函数，输入输出确定，工具自己不做判断。</li><li><strong>A2A（Agent2Agent）</strong>：把 Agent 彼此连起来。通过 A2A 找的是另一个 Agent，它有自己的模型、工具和记忆，对你是个黑盒，可能跑很久，中途还会回头问你要信息。</li></ul><p>简单说：Skill 是 Agent 自己的做事方法，MCP 接的是它手边的工具，A2A 是把活交给另一个 Agent。</p><h2 id="六、结果汇总与冲突处理" tabindex="-1">六、结果汇总与冲突处理 <a class="header-anchor" href="#六、结果汇总与冲突处理" aria-label="Permalink to &quot;六、结果汇总与冲突处理&quot;">​</a></h2><h3 id="_6-1-汇总-只用交回来的东西" tabindex="-1">6.1 汇总：只用交回来的东西 <a class="header-anchor" href="#_6-1-汇总-只用交回来的东西" aria-label="Permalink to &quot;6.1 汇总：只用交回来的东西&quot;">​</a></h3><p>并行分片时，子 Agent 要按统一格式交结果，带上出处。汇总按字段合并、去重、标出冲突，不要把几份报告丢给模型自由改写。</p><p>主 Agent 汇总时容易出现幻觉——报告太多太长导致漏看或看混、模型用自己的知识补空缺、转述时改了数字和限定词、几份报告有冲突被揉成了一个读起来通顺的说法。约束方法：</p><ul><li>每条结论都标出来自哪个子 Agent 的哪条证据，标不出来的不写</li><li>汇总后加一道核对，逐条检查结论在子 Agent 的结果里有没有依据</li><li>关键的数字和名称照抄，不让模型改写</li><li>汇总这一步不给检索工具，免得它半路自己找新材料</li></ul><h3 id="_6-2-两个-agent-说法矛盾" tabindex="-1">6.2 两个 Agent 说法矛盾 <a class="header-anchor" href="#_6-2-两个-agent-说法矛盾" aria-label="Permalink to &quot;6.2 两个 Agent 说法矛盾&quot;">​</a></h3><p>当两个执行 Agent 对同一个业务事实给出了矛盾的结果时：</p><ol><li><strong>先确认是不是真冲突</strong>：时间点不同、统计口径不同、数据来源不同，都会让两个说法看起来矛盾。</li><li><strong>再按规则采信</strong>：权威数据源优先于文档，文档优先于模型推断；新版本优先于旧版本；有证据的优先于没证据的。</li><li><strong>规则判不了就去查</strong>：直接调权威系统核实，或者派一个 Agent 专门复核；还判不了，交给人。</li><li><strong>冲突写进结果里</strong>：不能让汇总的模型自己挑一个了事。</li></ol><p>也可以用投票：让几个 Agent 做同一件事，少数服从多数。但投票只在各自出错的原因互不相关时才有用——用的是同一个模型、读的是同一份错误资料，几票会一起错。</p><h3 id="_6-3-critic-检查要有依据" tabindex="-1">6.3 Critic：检查要有依据 <a class="header-anchor" href="#_6-3-critic-检查要有依据" aria-label="Permalink to &quot;6.3 Critic：检查要有依据&quot;">​</a></h3><p>Critic 检查最好有客观依据：测试能不能过，格式对不对，每条结论有没有出处，需求清单上的项做没做到。主观的部分，用评分标准让模型打分。</p><p>Critic 最好有独立的上下文，只看需求和产出，不看执行者的推理过程；能接上测试结果、工具返回这类外部信号更好；条件允许，可以换一个模型。</p><p>不通过以后，Critic 要给出具体的问题和证据：哪条测试没过，哪条结论缺出处。执行者按清单改，而不是整个重做。防止反复循环可以设最多轮数、连续两轮问题数没有减少就停、整体预算到线也停。</p><h3 id="_6-4-防止幻觉放大" tabindex="-1">6.4 防止幻觉放大 <a class="header-anchor" href="#_6-4-防止幻觉放大" aria-label="Permalink to &quot;6.4 防止幻觉放大&quot;">​</a></h3><p>在一条链路上，上游的一句猜测，到了下游就成了已知事实，再往下传，就没人记得它没验证过。防止幻觉放大的办法：</p><ul><li>让证据跟着结论走：结论和出处一起传，没有出处的标「未核实」</li><li>下游把上游的输出当成说法，而不是事实</li><li>关键事实在交接处核对一次</li><li>最终的引用能追到原始出处</li></ul><h2 id="七、工程上要管住的几件事" tabindex="-1">七、工程上要管住的几件事 <a class="header-anchor" href="#七、工程上要管住的几件事" aria-label="Permalink to &quot;七、工程上要管住的几件事&quot;">​</a></h2><h3 id="_7-1-子-agent-失败与超时" tabindex="-1">7.1 子 Agent 失败与超时 <a class="header-anchor" href="#_7-1-子-agent-失败与超时" aria-label="Permalink to &quot;7.1 子 Agent 失败与超时&quot;">​</a></h3><ul><li>每个子 Agent 设超时和步数上限</li><li>偶发错误自动重试，次数有限；同样错误反复出现就别再试</li><li>失败了也带着做完的部分返回，写清楚做到哪一步、哪些还没核实</li><li>长任务要能续跑，从出错的地方恢复而不是从头再来</li><li>有副作用的操作（写库、发消息、下单）要幂等</li></ul><p>多 Agent 的成功率是一环一环乘出来的：五个环节各有 95% 的成功率，互相独立、出错也不重试的话，整体只有 77% 左右。</p><h3 id="_7-2-预算要覆盖所有-agent" tabindex="-1">7.2 预算要覆盖所有 Agent <a class="header-anchor" href="#_7-2-预算要覆盖所有-agent" aria-label="Permalink to &quot;7.2 预算要覆盖所有 Agent&quot;">​</a></h3><p>预算只写在题面里是不够的。主 Agent 和子 Agent 都只看得到自己那一部分，总量得由运行系统统一汇总，到线就停。做法是开工前给各个子 Agent 留出份额，运行时持续累加主 Agent 和所有子 Agent 的用量，时间和 token 两项都看，哪个先到就停。</p><h3 id="_7-3-权限各管各的" tabindex="-1">7.3 权限各管各的 <a class="header-anchor" href="#_7-3-权限各管各的" aria-label="Permalink to &quot;7.3 权限各管各的&quot;">​</a></h3><p>默认不该全给，按最小权限来：做检索、做审查的只读；做实现的只能写自己的工作目录或分支；发消息、写生产数据、部署这类有副作用的操作，要么只留给主 Agent，要么要人确认。</p><h3 id="_7-4-链路追踪与分-agent-记账" tabindex="-1">7.4 链路追踪与分 Agent 记账 <a class="header-anchor" href="#_7-4-链路追踪与分-agent-记账" aria-label="Permalink to &quot;7.4 链路追踪与分 Agent 记账&quot;">​</a></h3><p>一个任务一个 trace ID，每个子 Agent 是其中一段，记下它收到的任务说明、调用的工具、交回的结果，用了多少 token、多少时间。出了问题才能定位是哪个 Agent 引入的错；成本也才能分到每个 Agent 头上。</p><h3 id="_7-5-评测-先有单-agent-基线" tabindex="-1">7.5 评测：先有单 Agent 基线 <a class="header-anchor" href="#_7-5-评测-先有单-agent-基线" aria-label="Permalink to &quot;7.5 评测：先有单 Agent 基线&quot;">​</a></h3><p>做多 Agent 改进之前，先跑单 Agent 基线：</p><ul><li><strong>端到端评测</strong>：同一批任务，单 Agent 基线和多 Agent 各跑几遍，比成功率或质量分、耗时、token 和费用。Agent 每次跑的结果都不一样，跑一遍不够。</li><li><strong>分环节评测</strong>：路由选对的比例，每个子 Agent 的完成率，Critic 判对的比例，汇总后的结论有多少能在子 Agent 的结果里找到依据。</li><li><strong>起步不用大</strong>：用大约 20 个代表真实用法的问题起步，用模型打分，也做人工测试。</li></ul><h2 id="八、新算力环境-vs-多-agent-是基础设施-不是替代品" tabindex="-1">八、新算力环境 vs 多 Agent：是基础设施，不是替代品 <a class="header-anchor" href="#八、新算力环境-vs-多-agent-是基础设施-不是替代品" aria-label="Permalink to &quot;八、新算力环境 vs 多 Agent：是基础设施，不是替代品&quot;">​</a></h2><p>在 Codex 等 AI 编程助手中，让模型&quot;创建一个新的算力环境&quot;（沙盒、独立工作区）来处理特定任务，这种模式与多 Agent 架构在<strong>目标和效果上非常相似，但本质上有明显区别</strong>。严格来说，它属于「单智能体 + 隔离工具环境」（Single-Agent with Isolated Environment/Tool Use），是多 Agent 架构的底层基础设施，而非多 Agent 本身。</p><h3 id="为什么它们看起来极其相似" tabindex="-1">为什么它们看起来极其相似？ <a class="header-anchor" href="#为什么它们看起来极其相似" aria-label="Permalink to &quot;为什么它们看起来极其相似？&quot;">​</a></h3><p>无论是开辟新算力环境还是引入新 Agent，核心目的都是解决三件事：</p><ul><li><strong>状态隔离与防污染</strong>：将特定任务扔到全新环境中执行，保证主上下文的纯洁性，避免大模型&quot;注意力稀释&quot;或产生幻觉。</li><li><strong>物理工作区边界</strong>：新环境提供干净的内存空间、文件系统和依赖树，避免读写冲突。</li><li><strong>任务降维</strong>：将&quot;大问题&quot;拆解为&quot;小问题&quot;，在限定范围内求解，只把结果（而非过程）返回主控流。</li></ul><h3 id="核心差异-控制权与系统提示词在哪" tabindex="-1">核心差异：控制权与系统提示词在哪 <a class="header-anchor" href="#核心差异-控制权与系统提示词在哪" aria-label="Permalink to &quot;核心差异：控制权与系统提示词在哪&quot;">​</a></h3><p>区分两者的关键在于&quot;控制权（Agency）&quot;和&quot;系统提示词（Persona/System Prompt）&quot;归属谁。</p><p><strong>新算力/沙盒是被动的执行环境。</strong> 当 AI 创建一个新环境跑代码时，环境里并没有另一个&quot;独立思考的 AI&quot;——依然是原来的主 AI 大脑在向新环境发送指令、写入代码、读取执行结果。这相当于一个程序员打开了一个新的虚拟机终端。交互语言是<strong>代码与执行日志</strong>。</p><p><strong>多 Agent 包含多个主动的思考节点。</strong> 如果主控 Agent 召唤了一个&quot;数据库专家 Agent&quot;，这个子 Agent 拥有独立的 System Prompt、独立的思考循环（Thought/Action/Observation），遇到报错会自己决定如何修复，最后只把结论汇报给主 Agent。这相当于一个程序员把任务外包给了另一个专职的 DBA。交互语言通常是<strong>自然语言或结构化 JSON 协议</strong>。</p><p>此外，创建新算力主要实现的是<strong>物理与状态隔离</strong>（内存清空、变量重置、文件系统干净），而多 Agent 不仅需要物理隔离，更强调<strong>逻辑与视角的隔离</strong>——不同 Agent 拥有截然不同的 Prompt 和关注点，单靠一个&quot;新算力环境&quot;无法提供这种多维度的认知隔离。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>多 Agent 架构不是一道「要不要用」的选择题，而是一道「在什么条件下用、怎么用」的设计题。核心思路可以概括为：</p><ul><li><strong>拆</strong>：上下文隔离、工具隔离、职责分离、并行加速——每种理由对应不同的拆分策略</li><li><strong>通信</strong>：主中转、黑板、直接对话——各有取舍，没有银弹</li><li><strong>汇总</strong>：字段化回传、证据绑定、独立检查——防止幻觉放大和决策冲突</li><li><strong>工程</strong>：失败兜底、预算管控、权限隔离、链路追踪、对照评测——让系统可观测、可调试、可度量</li></ul><p>记住一个原则：比讲道理更有说服力的是对照数据。在决定引入多 Agent 之前，先跑通单 Agent 基线，用数据说话。</p><p>让 AI 新开一个环境去跑代码，是<strong>利用工具隔离上下文</strong>的优秀工程实践，相当于为单一智能体提供了一个&quot;草稿本&quot;或&quot;隔离实验室&quot;。只有当进入新算力环境的，是一个携带全新系统指令、拥有自主规划能力，并与其他环境中的 AI 进行对话协作的独立模型实例时，这个架构才真正进化成了多 Agent 系统。两者并不矛盾——隔离的算力环境，往往正是运行复杂多 Agent 协作的最佳底座。</p>',103)])])}const p=e(l,[["render",o]]);export{u as __pageData,p as default};
